css:
.loader {
  position: relative;
  width: 46px;
  height: 52px;
}
.loader i {
  position: absolute;
  top: 0;
  left: 50%;
  width: 26px;
  height: 18px;
  margin-left: -13px;
  border: 1px solid #c7d2fe;
  box-sizing: border-box;
  background-color: #eef2ff;
  background-image: repeating-linear-gradient(#c7d2fe 0 1px, transparent 1px 4px);
  background-repeat: no-repeat;
  animation: feed 1.6s ease-in-out infinite;
}
.loader::before {
  content: "";
  position: absolute;
  top: 20px;
  left: 2px;
  right: 2px;
  height: 10px;
  border-radius: 2px;
  background: #6366f1;
  z-index: 2;
}
.loader::after {
  content: "";
  position: absolute;
  top: 32px;
  left: 8px;
  width: 30px;
  height: 20px;
  background: repeating-linear-gradient(90deg, #6366f1 0 3px, transparent 3px 5px);
  animation: strips 1.6s ease-in-out infinite;
}
@keyframes feed {
  0% { top: 0; }
  55% { top: 16px; }
  100% { top: 16px; }
}
@keyframes strips {
  0%, 45% { opacity: 0; transform: translateY(-4px); }
  60% { opacity: 1; }
  100% { opacity: 1; transform: translateY(4px); }
}
